import React, { useState, useEffect, useCallback, useMemo, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAppContext } from '../context/AppContext';
import { Button } from '../components/ui/button';
import { Input } from '../components/ui/input';
import { Card, CardContent, CardHeader, CardTitle } from '../components/ui/card';
import { Badge } from '../components/ui/badge';
import { formatRupiah } from '../lib/utils';
import GoogleMapComponent, { geocodeAddress, reverseGeocode } from '../components/GoogleMap';
import { MapPin, Ticket, ShieldCheck, CreditCard, AlertCircle, CheckCircle2, Search, Crosshair } from 'lucide-react';
import { api } from '../lib/utils';
import { fmtQty } from '../lib/qty';
import { DEFAULT_SHIPPING, distanceKm, shippingFee as calcShippingFee, freeShippingGap, fmtKm } from '../lib/shipping';

const MIDTRANS_CLIENT_KEY = 'Mid-client-viGLekjKyOUm4QLa';
// Jika key diawali Mid- biasanya production, namun jika diset sandbox pakai URL sandbox
const IS_SANDBOX = true; 
const SNAP_URL = IS_SANDBOX 
  ? 'https://app.sandbox.midtrans.com/snap/snap.js' 
  : 'https://app.midtrans.com/snap/snap.js';

export default function Checkout() {
  const { cart, clearCart, user } = useAppContext();
  const navigate = useNavigate();

  // Form State
  const [customerName, setCustomerName] = useState(user?.name || '');
  const [customerPhone, setCustomerPhone] = useState(user?.phone || '');
  const [customerEmail, setCustomerEmail] = useState(user?.email || '');
  const [address, setAddress] = useState('');
  const [notes, setNotes] = useState('');

  // Voucher State
  const [voucherCode, setVoucherCode] = useState('');
  const [appliedVoucher, setAppliedVoucher] = useState(null);
  const [voucherError, setVoucherError] = useState('');

  // Loading & Payment State
  const [isProcessing, setIsProcessing] = useState(false);
  const [snapReady, setSnapReady] = useState(false);

  // Perhitungan Biaya
  const subtotal = cart.reduce((acc, item) => acc + Math.round(item.price * item.quantity), 0);
  // Lokasi pengantaran & ongkir (aturan dari pengaturan admin; server menghitung ulang saat pesanan dibuat)
  const [cfg, setCfg] = useState(DEFAULT_SHIPPING);
  const [pin, setPin] = useState(null);
  const [locStatus, setLocStatus] = useState({ busy: false, bad: false, msg: '' });
  const pinRef = useRef(null);
  useEffect(() => { pinRef.current = pin; }, [pin]);
  // Objek ini harus stabil (useMemo) agar peta tidak bergeser sendiri setiap form diketik
  const store = useMemo(() => ({ lat: Number(cfg.store_lat), lng: Number(cfg.store_lng) }), [cfg.store_lat, cfg.store_lng]);
  const maxRadius = Number(cfg.max_radius_km) || 0;
  const radiusCircle = useMemo(() => (maxRadius > 0 ? { center: store, radiusKm: maxRadius } : null), [store, maxRadius]);
  const distance = pin ? distanceKm(store, pin) : null;
  const outOfRange = distance !== null && maxRadius > 0 && distance > maxRadius;
  const shippingFee = distance !== null && !outOfRange ? calcShippingFee(cfg, distance, subtotal) : null;
  const freeGap = shippingFee ? freeShippingGap(cfg, distance, subtotal) : null;

  // Diskon Voucher
  const discountAmount = appliedVoucher ? Math.min(appliedVoucher.discount, subtotal) : 0;

  const grandTotal = Math.max(0, subtotal + (shippingFee || 0) - discountAmount);

  // Load Script Midtrans Snap secara dinamis
  useEffect(() => {
    const existingScript = document.getElementById('midtrans-snap-script');
    if (!existingScript) {
      const script = document.createElement('script');
      script.id = 'midtrans-snap-script';
      script.src = SNAP_URL;
      script.setAttribute('data-client-key', MIDTRANS_CLIENT_KEY);
      script.onload = () => setSnapReady(true);
      document.body.appendChild(script);
    } else {
      setSnapReady(true);
    }
  }, []);

  // Ambil pengaturan toko & ongkir dari server
  useEffect(() => {
    api.get('/shipping/config')
      .then((r) => setCfg({ ...DEFAULT_SHIPPING, ...r.data.data }))
      .catch(() => {});
  }, []);

  // Tandai titik pengantaran (klik peta / geser pin). Alamat terisi otomatis bila kolom masih kosong.
  const setPoint = useCallback(async (p) => {
    setPin(p);
    setLocStatus({ busy: false, bad: false, msg: '' });
    const label = await reverseGeocode(p);
    if (label) setAddress((prev) => (prev.trim() ? prev : label));
  }, []);

  // auto = true: dipicu otomatis saat kolom alamat ditinggalkan; hasilnya tidak menimpa titik yang sudah dipilih pembeli.
  const handleSearch = async (auto = false) => {
    if (address.trim().length < 5) {
      setLocStatus({ busy: false, bad: true, msg: 'Tulis alamat dulu (jalan, kelurahan, kota), lalu klik Cari di peta.' });
      return;
    }
    setLocStatus({ busy: true, bad: false, msg: 'Mencari alamat…' });
    try {
      const r = await geocodeAddress(address, store);
      if (auto && pinRef.current) { setLocStatus({ busy: false, bad: false, msg: '' }); return; }
      setPin({ lat: r.lat, lng: r.lng });
      setLocStatus({ busy: false, bad: false, msg: 'Lokasi ditemukan. Geser pin merah bila belum tepat di rumah Anda.' });
    } catch (e) {
      setLocStatus({ busy: false, bad: true, msg: e.message });
    }
  };

  const handleLocate = () => {
    if (!navigator.geolocation) {
      setLocStatus({ busy: false, bad: true, msg: 'Browser Anda tidak mendukung deteksi lokasi. Klik langsung di peta.' });
      return;
    }
    setLocStatus({ busy: true, bad: false, msg: 'Mendeteksi lokasi Anda…' });
    navigator.geolocation.getCurrentPosition(
      (pos) => {
        setPoint({ lat: pos.coords.latitude, lng: pos.coords.longitude });
        setLocStatus({ busy: false, bad: false, msg: 'Lokasi terdeteksi. Geser pin merah bila perlu.' });
      },
      () => setLocStatus({ busy: false, bad: true, msg: 'Lokasi tidak dapat diakses. Izinkan akses lokasi di browser, atau klik langsung di peta.' }),
      { enableHighAccuracy: true, timeout: 12000 }
    );
  };

  const handleApplyVoucher = async (e) => {
    e.preventDefault();
    setVoucherError('');
    try {
      const res = await api.post('/vouchers/validate', { code: voucherCode.trim().toUpperCase(), subtotal });
      setAppliedVoucher(res.data.data);
    } catch (err) {
      setAppliedVoucher(null);
      const m = err.response?.data?.message || '';
      setVoucherError(
        m.startsWith('Minimum spend') ? 'Belum mencapai minimal belanja voucher ini' :
        m === 'Voucher expired' ? 'Voucher sudah kedaluwarsa' :
        m === 'Voucher quota exceeded' ? 'Kuota voucher sudah habis' :
        err.response?.status === 401 ? 'Silakan masuk dulu untuk memakai voucher' :
        'Kode voucher tidak ditemukan atau tidak aktif'
      );
    }
  };

  const handlePay = async (e) => {
    e.preventDefault();
    if (!user) {
      navigate('/auth');
      return;
    }
    if (!address.trim()) {
      alert('Mohon isi alamat pengiriman lengkap Anda');
      return;
    }
    if (!pin) {
      alert('Tandai lokasi pengantaran di peta terlebih dahulu');
      return;
    }
    if (outOfRange) {
      alert('Alamat Anda di luar jangkauan pengiriman');
      return;
    }

    setIsProcessing(true);

    try {
      // 1. Coba request Snap Token ke backend API
      let snapToken = null;
      try {
        const res = await api.post('/orders', {
          items: cart,
          subtotal,
          discount: discountAmount,
          voucher_code: appliedVoucher?.code || null,
          address,
          notes,
          name: customerName,
          phone: customerPhone,
          email: customerEmail,
          lat: pin.lat,
          lng: pin.lng
        });

        if (res.data?.payment_token) {
          snapToken = res.data.payment_token;
        }
      } catch (apiErr) {
        if (apiErr?.response?.status === 401) {
          alert('Sesi login berakhir. Silakan masuk kembali.');
          navigate('/auth');
        } else {
          alert(apiErr?.response?.data?.message || 'Gagal membuat pesanan. Coba lagi.');
        }
        setIsProcessing(false);
        return;
      }

      // 2. Jika window.snap tersedia dan ada token, buka popup Snap Midtrans
      if (window.snap && snapToken) {
        window.snap.pay(snapToken, {
          onSuccess: function (result) {
            clearCart();
            navigate(`/payment-result?status=success&order_id=${result.order_id}`);
          },
          onPending: function (result) {
            clearCart();
            navigate(`/payment-result?status=pending&order_id=${result.order_id}`);
          },
          onError: function (result) {
            alert('Pembayaran gagal atau dibatalkan oleh bank');
            setIsProcessing(false);
          },
          onClose: function () {
            setIsProcessing(false);
          }
        });
      } else {
        alert('Pembayaran belum dapat diproses. Muat ulang halaman lalu coba lagi.');
        setIsProcessing(false);
      }
    } catch (err) {
      console.error(err);
      alert('Terjadi kesalahan saat memproses pesanan.');
      setIsProcessing(false);
    }
  };

  if (cart.length === 0) {
    return (
      <div className="min-h-[60vh] flex flex-col items-center justify-center text-center px-4">
        <div className="w-16 h-16 rounded-full bg-emerald-100 text-emerald-600 flex items-center justify-center text-2xl mb-4 font-bold">
          🥬
        </div>
        <p className="text-xl font-bold text-gray-800 mb-2">Keranjang Anda Masih Kosong</p>
        <p className="text-gray-500 mb-6 text-sm">Pilih sayuran dan buah segar dari petani sebelum checkout.</p>
        <Button onClick={() => navigate('/')} className="bg-emerald-600 hover:bg-emerald-700">
          Mulai Belanja Sayur & Buah
        </Button>
      </div>
    );
  }

  return (
    <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-10">
      <div className="mb-8">
        <h1 className="text-3xl font-extrabold text-gray-900 tracking-tight">Checkout Pesanan</h1>
        <p className="text-sm text-gray-500 mt-1">
          Selesaikan pesanan Anda dengan aman melalui gateway pembayaran Midtrans
        </p>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        {/* Kolom Kiri: Data Pengiriman & Alamat */}
        <div className="lg:col-span-2 space-y-6">
          {/* Informasi Penerima */}
          <Card className="border-slate-200 shadow-sm">
            <CardHeader className="border-b border-slate-100 pb-4">
              <CardTitle className="text-base font-bold text-slate-800 flex items-center gap-2">
                <span className="w-6 h-6 rounded-full bg-emerald-100 text-emerald-700 text-xs flex items-center justify-center font-bold">1</span>
                Informasi Penerima
              </CardTitle>
            </CardHeader>
            <CardContent className="p-6 space-y-4">
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                <div>
                  <label className="text-xs font-semibold text-slate-700">Nama Lengkap</label>
                  <Input 
                    value={customerName} 
                    onChange={(e) => setCustomerName(e.target.value)} 
                    placeholder="Nama penerima..."
                    className="mt-1"
                  />
                </div>
                <div>
                  <label className="text-xs font-semibold text-slate-700">Nomor WhatsApp / HP</label>
                  <Input 
                    value={customerPhone} 
                    onChange={(e) => setCustomerPhone(e.target.value)} 
                    placeholder="08xxxxxxxxxx"
                    className="mt-1 font-mono"
                  />
                </div>
              </div>
              <div>
                <label className="text-xs font-semibold text-slate-700">Alamat Email (untuk bukti nota bayar)</label>
                <Input 
                  value={customerEmail} 
                  onChange={(e) => setCustomerEmail(e.target.value)} 
                  placeholder="email@anda.com"
                  className="mt-1"
                />
              </div>
            </CardContent>
          </Card>

          {/* Alamat & Titik Pengiriman Google Maps */}
          <Card className="border-slate-200 shadow-sm">
            <CardHeader className="border-b border-slate-100 pb-4">
              <CardTitle className="text-base font-bold text-slate-800 flex items-center gap-2">
                <span className="w-6 h-6 rounded-full bg-emerald-100 text-emerald-700 text-xs flex items-center justify-center font-bold">2</span>
                Alamat & Lokasi Google Maps
              </CardTitle>
            </CardHeader>
            <CardContent className="p-6 space-y-4">
              <div className="h-72 rounded-xl overflow-hidden border border-slate-200 shadow-inner">
                <GoogleMapComponent
                  store={store}
                  pin={pin}
                  onPinChange={setPoint}
                  onMapClick={setPoint}
                  circle={radiusCircle}
                />
              </div>
              <p className="text-xs text-slate-500">
                Klik peta atau geser pin merah ke titik rumah Anda. Pin hijau adalah lokasi toko.
              </p>

              {/* Status lokasi, jarak & ongkir */}
              {!pin ? (
                <div className="flex items-start gap-2 p-2.5 bg-amber-50 rounded-lg text-xs text-amber-800">
                  <MapPin className="h-4 w-4 flex-shrink-0 mt-0.5" />
                  <span>Tandai lokasi pengantaran dulu: cari alamat Anda, gunakan lokasi saya, atau klik langsung di peta.</span>
                </div>
              ) : outOfRange ? (
                <div className="flex items-start gap-2 p-2.5 bg-red-50 rounded-lg text-xs text-red-700">
                  <AlertCircle className="h-4 w-4 flex-shrink-0 mt-0.5" />
                  <span>Lokasi ini berjarak <strong>{fmtKm(distance)}</strong> dari toko, di luar jangkauan pengiriman (maksimal {fmtKm(maxRadius)}). Pilih titik lain atau hubungi toko.</span>
                </div>
              ) : (
                <div className="flex items-start gap-2 p-2.5 bg-emerald-50 rounded-lg text-xs text-emerald-800">
                  <MapPin className="h-4 w-4 text-emerald-600 flex-shrink-0 mt-0.5" />
                  <span>
                    Jarak <strong>{fmtKm(distance)}</strong> dari toko WiwikSayur.id.{' '}
                    {shippingFee === 0 ? <strong>Gratis ongkir untuk pesanan ini.</strong> : (
                      <>Ongkir <strong>{formatRupiah(shippingFee)}</strong>.{freeGap ? <> Tambah belanja <strong>{formatRupiah(freeGap)}</strong> lagi untuk gratis ongkir.</> : null}</>
                    )}
                  </span>
                </div>
              )}

              <div>
                <label className="text-xs font-semibold text-slate-700">Alamat Lengkap Pengiriman</label>
                <textarea 
                  value={address}
                  onChange={(e) => setAddress(e.target.value)}
                  onBlur={() => { if (!pin && address.trim().length >= 12 && !locStatus.busy) handleSearch(true); }}
                  rows={3}
                  className="mt-1 w-full rounded-md border border-input bg-background px-3 py-2 text-sm focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-emerald-500"
                  placeholder="Tulis nama jalan, nomor rumah, RT/RW, kelurahan, patokan khusus..."
                />
                <div className="mt-2 flex flex-wrap gap-2">
                  <Button type="button" variant="outline" onClick={() => handleSearch()} disabled={locStatus.busy} className="h-9 text-xs gap-1.5">
                    <Search className="h-3.5 w-3.5" /> Cari di peta
                  </Button>
                  <Button type="button" variant="outline" onClick={handleLocate} disabled={locStatus.busy} className="h-9 text-xs gap-1.5">
                    <Crosshair className="h-3.5 w-3.5" /> Gunakan lokasi saya
                  </Button>
                </div>
                {locStatus.msg && (
                  <p className={`mt-2 text-xs ${locStatus.bad ? 'text-red-600' : 'text-slate-500'}`}>{locStatus.msg}</p>
                )}
              </div>
              <div>
                <label className="text-xs font-semibold text-slate-700">Catatan untuk Penjual / Kurir (Opsional)</label>
                <Input 
                  value={notes} 
                  onChange={(e) => setNotes(e.target.value)} 
                  placeholder="Contoh: Titip di satpam / sayuran tolong yang segar baru panen"
                  className="mt-1"
                />
              </div>
            </CardContent>
          </Card>
        </div>

        {/* Kolom Kanan: Rincian Belanja & Pembayaran Midtrans */}
        <div className="space-y-6">
          <Card className="border-slate-200 shadow-sm sticky top-24">
            <CardHeader className="border-b border-slate-100 pb-4">
              <CardTitle className="text-base font-bold text-slate-800">Ringkasan Belanja</CardTitle>
            </CardHeader>
            <CardContent className="p-6 space-y-5">
              {/* Daftar Barang */}
              <div className="space-y-3 max-h-60 overflow-y-auto pr-1 text-sm divide-y divide-slate-100">
                {cart.map((item) => (
                  <div key={item.id} className="pt-2 flex justify-between items-center text-xs">
                    <div>
                      <p className="font-semibold text-slate-900">{item.name}</p>
                      <p className="text-slate-500">{fmtQty(item.quantity, item.unit)} × {formatRupiah(item.price)}/{item.unit}</p>
                    </div>
                    <span className="font-mono font-bold text-slate-800">
                      {formatRupiah(Math.round(item.price * item.quantity))}
                    </span>
                  </div>
                ))}
              </div>

              {/* Form Input Voucher */}
              <div className="border-t border-slate-100 pt-4">
                <label className="text-xs font-semibold text-slate-700 flex items-center gap-1.5 mb-1.5">
                  <Ticket className="h-3.5 w-3.5 text-emerald-600" /> Punya Kode Voucher?
                </label>
                <div className="flex gap-2">
                  <Input 
                    value={voucherCode} 
                    onChange={(e) => setVoucherCode(e.target.value.toUpperCase())}
                    placeholder="Contoh: SEGAR20"
                    className="text-xs uppercase font-mono"
                  />
                  <Button 
                    type="button" 
                    onClick={handleApplyVoucher}
                    variant="outline" 
                    className="text-xs px-3"
                  >
                    Gunakan
                  </Button>
                </div>
                {appliedVoucher && (
                  <div className="mt-2 p-2 bg-emerald-50 rounded text-xs text-emerald-700 flex items-center justify-between">
                    <span className="font-semibold">Voucher &quot;{appliedVoucher.code}&quot; aktif!</span>
                    <button onClick={() => setAppliedVoucher(null)} className="text-red-600 hover:underline">Hapus</button>
                  </div>
                )}
                {voucherError && (
                  <p className="text-xs text-red-600 mt-1 flex items-center gap-1">
                    <AlertCircle className="h-3 w-3" /> {voucherError}
                  </p>
                )}
              </div>

              {/* Breakdown Biaya */}
              <div className="border-t border-slate-100 pt-4 space-y-2 text-xs">
                <div className="flex justify-between text-slate-600">
                  <span>Subtotal Sayur & Buah</span>
                  <span className="font-mono font-semibold">{formatRupiah(subtotal)}</span>
                </div>
                <div className="flex justify-between text-slate-600">
                  <span>Ongkos Kirim{shippingFee !== null ? ` (${fmtKm(distance)})` : ''}</span>
                  <span className="font-mono font-semibold">
                    {shippingFee === null ? <span className="font-sans font-normal text-slate-400">{outOfRange ? 'Di luar jangkauan' : 'Pilih lokasi'}</span>
                      : shippingFee === 0 ? <strong className="text-emerald-700">GRATIS</strong> : formatRupiah(shippingFee)}
                  </span>
                </div>
                {discountAmount > 0 && (
                  <div className="flex justify-between text-emerald-700 font-semibold">
                    <span>Diskon Voucher</span>
                    <span className="font-mono">- {formatRupiah(discountAmount)}</span>
                  </div>
                )}
                <div className="border-t border-slate-200 pt-3 flex justify-between items-center text-sm font-bold text-slate-900">
                  <span>Total Tagihan</span>
                  <span className="font-mono text-emerald-700 text-lg">{formatRupiah(grandTotal)}</span>
                </div>
              </div>

              {/* Tombol Bayar Midtrans */}
              <div className="pt-2 space-y-3">
                <Button 
                  onClick={handlePay} 
                  disabled={isProcessing || !pin || outOfRange} 
                  className="w-full bg-emerald-600 hover:bg-emerald-700 text-white font-bold h-12 flex items-center justify-center gap-2 shadow-md shadow-emerald-700/20"
                >
                  <CreditCard className="h-4 w-4" />
                  {isProcessing ? 'Memproses Gateway...' : !pin ? 'Tandai Lokasi Pengantaran' : outOfRange ? 'Di Luar Jangkauan' : 'Bayar Sekarang via Midtrans'}
                </Button>

                {/* Badge Keamanan */}
                <div className="flex items-center justify-center gap-2 text-[11px] text-slate-400">
                  <ShieldCheck className="h-4 w-4 text-emerald-600" />
                  <span>Didukung Midtrans Snap (BCA, Mandiri, QRIS, GoPay)</span>
                </div>
              </div>
            </CardContent>
          </Card>
        </div>
      </div>
    </div>
  );
}
